try {schoolState=load(localStorage);state=schoolState;}catch(e){schoolState=seed();state=schoolState;storageBroken=true;storageWarning(e.message);}
function storageWarning(message){const el=$('#storage-warning');el.hidden=false;el.textContent=`Local saving unavailable: ${message} Current saved data has not been overwritten.`;}
async function mutate(fn){if(!currentTeacher)return false;if(savingWorkspace){toast('Please wait for the current save to finish.');return false;}if(storageBroken&&!sharedWorkspace){toast('Saving is unavailable. Export your backup first.');return false;}savingWorkspace=true;try{const next=structuredClone(state);fn(next);let merged;if(sharedWorkspace){const response=await fetch('/api/workspace',{method:'PUT',headers:{'Content-Type':'application/json'},body:JSON.stringify({state:next,expectedRevision:workspaceRevision})});const result=await response.json();if(!response.ok)throw Error(result.error||'Shared workspace could not be saved.');merged=result.state;workspaceRevision=result.revision;try{localStorage.setItem(STORAGE_KEY,JSON.stringify(merged));}catch{}}else{const latest=load(localStorage);merged=mergeTeacherState(latest,next,currentTeacher.id);localStorage.setItem(STORAGE_KEY,JSON.stringify(merged));}schoolState=merged;state=scopedState(merged,currentTeacher.id);return true;}catch(error){showError(error.message);return false;}finally{savingWorkspace=false;}}
async function syncWorkspace(){const response=await fetch('/api/workspace',{cache:'no-store'});const result=await response.json();if(!response.ok)throw Error(result.error||'Could not load your shared workspace.');if(result.revision===0&&localStorage.getItem(STORAGE_KEY)){const imported=await fetch('/api/workspace/import',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({state:scopedState(schoolState,currentTeacher.id),expectedRevision:0})});if(imported.ok){const value=await imported.json();schoolState=value.state;workspaceRevision=value.revision;return;}toast('Earlier browser workspace records remain on this computer; they could not be imported automatically.');}schoolState=result.state;workspaceRevision=result.revision;}

function showError(message){const active=$('#dialog[open] .error')||$('#page-error');if(active){active.textContent=message;active.scrollIntoView({block:'nearest'});}else toast(message);}
let toastTimer;
