  const header=`<div class="eyebrow">MY CLASSES / ${yearLabel(c.year).toUpperCase()}</div><div class="class-header"><div>${subject(c)}</div><div><h1>${c.name}</h1><p>${esc(currentTeacher.name)} · ${roster(c.id).length} students · ${c.room}</p></div></div><nav class="tabs" aria-label="Class sections">${['dashboard','roster','assignments','gradebook','curriculum'].map(t=>`<a class="${tab===t?'active':''}" href="${href('/classes',{class:c.id,tab:t})}" ${tab===t?'aria-current="page"':''}>${t[0].toUpperCase()+t.slice(1)}</a>`).join('')}<a href="${href('/attendance',{class:c.id})}">Attendance ↗</a></nav>`+(tab==='dashboard'?homeTools.classAnnouncements(c):'');
