  if(tab==='roster')return header+`<section class="panel"><div class="panel-head"><h2>Class roster</h2><span class="muted">${roster(c.id).length} students</span></div>${studentTable(roster(c.id))}</section>`;
  if(tab==='assignments')return header+`<div class="section-label"><h2>Assignments</h2>${button(icon('plus')+' New assignment','assignment',`data-class="${c.id}"`,'primary')}</div><section class="panel">${assignments.length?`<div class="table-wrap"><table class="data-table"><thead><tr><th>Assignment</th><th>Due</th><th>Marks</th><th>Graded</th><th>Action</th></tr></thead><tbody>${assignments.map(a=>`<tr><td><strong>${esc(a.title)}</strong><p class="muted">${esc(a.description)}</p></td><td>${formatDate(a.due)}</td><td>${a.points}</td><td>${Object.keys(state.grades[a.id]||{}).length} / ${roster(c.id).length}</td><td><a class="text-button" href="${href('/classes',{class:c.id,tab:'gradebook',assignment:a.id})}">Enter marks →</a></td></tr>`).join('')}</tbody></table></div>`:empty('No assignments yet','Add an assignment to start recording marks.')}</section>`;
