function attendancePage(params){if(!params.get('class'))return attendanceOverviewUI.page(params);const c=currentClass(),date=isDate(params.get('date')||'')?params.get('date'):today(),period=periods.some(p=>p[0]===params.get('period'))?params.get('period'):'4';activeRegister={classId:c.id,date,period};const contextKey=keyFor(date,c.id,period),context=contextCache.get(contextKey);if(!context){void loadRegisterContext(activeRegister);return heading('Attendance','')+'<section class="panel"><div class="empty">Loading saved attendance and earlier lesson records…</div></section>';}if(context.error)return heading('Attendance','')+'<div id="page-error" class="error">'+esc(context.error)+'</div>'+button('Retry loading','retry-register');const saved=context.saved;draft=structuredClone(context.records);activeRegister.expectedRevision=context.revision;
return heading('Attendance','A clear register for every lesson. Save when you’re ready.',button(icon('download')+' Export CSV','attendance-export'),'CLASS REGISTERS')+`<div class="filters"><label class="field grow"><span>Class</span><select id="attendance-class">${classOptions(c.id)}</select></label><label class="field"><span>Date</span><input id="attendance-date" type="date" value="${date}" required></label><label class="field"><span>Period</span><select id="attendance-period">${options(periods.map(p=>[p[0],`${p[0]} · ${p[1]}–${p[2]}`]),period)}</select></label></div><section class="panel"><div class="panel-head"><div><h2>${c.name}</h2><p>${roster(c.id).length} students · ${formatDate(date)}</p></div><span id="attendance-summary" class="status-summary">${summaryHtml(draft)}</span></div><div class="panel-body">${button('✓ Mark all present','mark-present','','small')} <span class="muted"><small>Changes are saved only when you select Save attendance.</small></span></div><div id="page-error" class="error" role="alert"></div><div class="table-wrap"><table class="data-table"><thead><tr><th>Student</th><th>Attendance</th><th>Arrival time</th><th>Note</th></tr></thead><tbody>${draft.map(r=>attendanceRow(r)).join('')}</tbody></table></div></section><div class="save-bar"><span id="save-status">${saved?(saved.complete?'Saved ':'Incomplete register · ')+new Date(saved.updatedAt).toLocaleTimeString('en-GB',{hour:'2-digit',minute:'2-digit',timeZone:'Asia/Tashkent'}):(context.prefilledCount?context.prefilledCount+' prefilled · confirm and save':'Register not yet saved')}</span><div class="actions">${button('Cancel changes','cancel-draft')}${button('Back','register-back')}${button('Save attendance','save-attendance','','primary')}</div></div>`;}
function summaryHtml(records){const s=attendanceSummary(records);return badge(s.present+' present','present')+badge(s.late+' late','late')+badge(s.absent+' absent','absent')+(s.early?badge(s.early+' left early','late'):'')+(s.untaken?badge(s.untaken+' not taken','draft'):'');}
function attendanceRow(r){const s=studentById(r.studentId),late=r.status.startsWith('Late');return `<tr><td title="${r.prefilledFrom?esc('Prefilled from period '+r.prefilledFrom.period+' · '+(teacherById(r.prefilledFrom.teacherId)?.name||'Previous teacher')+' · '+r.prefilledFrom.status+' '+(r.prefilledFrom.time||'')):''}">${person(s)}${r.prefilledFrom?'<span class="carry-indicator" aria-label="Prefilled from an earlier lesson">↳</span>':''}</td><td><div class="register-status"><label class="sr-only" for="status-${s.id}">Attendance for ${s.name}</label><select id="status-${s.id}" data-register-status="${s.id}">${options(statuses,r.status)}</select></div></td><td class="arrival-cell"><button type="button" id="arrival-button-${s.id}" class="arrival-clock-button" data-action="arrival-time" data-id="${s.id}" aria-label="Arrival time for ${s.name}" title="Record the time this student arrived" ${late?'':'hidden'}>${icon('clock')}<span>${r.time||'Set time'}</span></button><span id="arrival-empty-${s.id}" class="muted" ${late?'hidden':''}>—</span></td><td><button id="note-button-${s.id}" class="btn small register-note-button ${r.note?'has-note':''}" data-action="register-note" data-id="${s.id}" aria-label="Attendance note for ${s.name}" title="${esc(r.note||'Add a lesson note')}">${r.note?'Note':'+ Note'}</button></td></tr>`;}
function currentArrivalTime(){return new Intl.DateTimeFormat('en-GB',{timeZone:'Asia/Tashkent',hour:'2-digit',minute:'2-digit',hourCycle:'h23'}).format(new Date());}
function updateArrivalCell(record){const late=record.status.startsWith('Late'),button=$('#arrival-button-'+record.studentId);button.hidden=!late;button.querySelector('span').textContent=record.time||'Set time';$('#arrival-empty-'+record.studentId).hidden=late;}
function arrivalTimeDialog(id){const record=draft.find(r=>r.studentId===id);if(!record||!record.status.startsWith('Late'))return;const student=studentById(id);openDialog('What time did they arrive?',`<p class="arrival-student">${esc(student.name)} <span class="badge late">${esc(record.status)}</span></p><form id="arrival-clock-form" data-id="${id}"><div class="field arrival-time-field"><label for="arrival-clock">Arrived at · Tashkent time</label><div class="arrival-minute-control"><input id="arrival-clock" name="time" type="time" step="60" value="${record.time||currentArrivalTime()}" required><div class="arrival-minute-arrows"><button type="button" class="btn" data-action="arrival-minute-up" aria-label="Increase arrival time by one minute" title="Add one minute">▲</button><button type="button" class="btn" data-action="arrival-minute-down" aria-label="Decrease arrival time by one minute" title="Subtract one minute">▼</button></div></div><small class="muted">Arrows adjust by 1 minute</small></div></form><button class="text-button" data-action="arrival-now">Use current time</button><p class="arrival-help muted">Apply the time, then Save attendance to save the register.</p>`,`${button('Cancel','close')}<button type="submit" form="arrival-clock-form" class="btn primary">Apply time</button>`);}
