function registerNoteDialog(id){const record=draft.find(r=>r.studentId===id);if(!record)return;const student=studentById(id);openDialog('Lesson note',`<p class="muted">${esc(student.name)}</p><br><form id="register-note-form"><label class="field"><span>Attendance note</span><textarea id="register-note-text" rows="4" maxlength="1000">${esc(record.note)}</textarea></label></form><br><small class="muted">This updates your draft. Select Save attendance to save the register.</small>`,`${button('Cancel','close')} ${button('Apply note','apply-register-note',`data-id="${id}"`,'primary')}`);}
function studentTable(list){return `<div class="table-wrap"><table class="data-table"><thead><tr><th>Student</th><th>Admission number</th><th>Form group</th><th>Teaching subjects</th><th>Action</th></tr></thead><tbody>${list.map(s=>`<tr><td>${person(s)}</td><td>${s.admissionNumber}</td><td>${s.groupName}</td><td>${classes.filter(c=>c.studentIds.includes(s.id)).map(c=>esc(c.subject)).join(', ')||'<span class="muted">—</span>'}</td><td>${button('View profile','student',`data-id="${s.id}"`,'small')}</td></tr>`).join('')}</tbody></table></div>`;}
function directoryResults(list,page=1){
  const pageSize=50,pages=Math.max(1,Math.ceil(list.length/pageSize)),current=Math.min(pages,Math.max(1,page)),start=(current-1)*pageSize;
  return `<div class="panel-head"><div><h2>${list.length.toLocaleString('en-GB')} ${list.length===1?'student':'students'}</h2><p>${list.length?`Showing ${start+1}–${Math.min(start+pageSize,list.length)}`:'No matching records'} · ${students.length.toLocaleString('en-GB')} in your allocation · ${groups.length} ${groups.length===1?'form':'forms'}</p></div><div class="heading-actions">${button('←','student-page',`data-page="${current-1}" aria-label="Previous student page" ${current===1?'disabled':''}`,'small')}<small class="muted">${current} / ${pages}</small>${button('→','student-page',`data-page="${current+1}" aria-label="Next student page" ${current===pages?'disabled':''}`,'small')}</div></div>${list.length?studentTable(list.slice(start,start+pageSize)):empty('No students found','Try a different name, admission number, year or form.')}`;
}
function directoryList(q='',year='',group=''){return students.filter(s=>(s.name+' '+s.admissionNumber).toLowerCase().includes(q.toLowerCase())&&(!year||String(s.year)===year)&&(!group||s.cohort===group));}
function groupOptions(year='',selected=''){return options([['','All forms'],...groups.filter(g=>!year||String(g.year)===year).map(g=>[g.id,`${g.name} · ${g.count} students`])],selected);}
