function cardsPage(params){return reportsUI.page(params);}
function assessmentsPage(){const assessedClasses=classes.filter(c=>!['assembly','registration','homeroom'].includes(c.kind));return heading('Assessment','Choose a class to enter marks, view percentages and open the student tracking sheets.','','ASSESSMENT & TRACKING')+`<div class="class-grid">${assessedClasses.map(c=>`<a class="panel assessment-access-card" href="${href('/classes',{class:c.id,tab:'gradebook'})}"><h2>${esc(c.name)}</h2><p>${esc(c.subject)} · ${roster(c.id).length} students</p><span class="text-button">Open assessment & tracking →</span></a>`).join('')}</div>`;}
