function render(){let {path,params}=readRoute();if(currentTeacher.role==='technician'&&path!=='/support'){history.replaceState(null,'','#/support');path='/support';params=new URLSearchParams();}if(currentTeacher.role==='parent'&&path!=='/family'){history.replaceState(null,'','#/family');path='/family';params=new URLSearchParams();}if(currentTeacher.role==='student'&&!['/classroom','/options'].includes(path)){history.replaceState(null,'','#/classroom');path='/classroom';params=new URLSearchParams();}document.body.classList.toggle('student-mode',['student','parent'].includes(currentTeacher.role));document.body.classList.toggle('parent-mode',currentTeacher.role==='parent');document.body.classList.toggle('timetable-view',path==='/timetable');document.body.classList.toggle('directory-view',path==='/directory');document.body.classList.toggle('directory-profile-view',path==='/person'||path==='/directory-class');document.body.classList.toggle('reviewer-view',currentTeacher.role==='report-reviewer');document.body.classList.toggle('report-entry-view',(path==='/cards'||currentTeacher.role==='report-reviewer'&&path==='/home')&&!params.get('student'));document.body.classList.toggle('report-detail-view',path==='/cards'&&Boolean(params.get('student')));document.body.classList.toggle('home-view',path==='/home'&&currentTeacher.role!=='report-reviewer');document.body.classList.toggle('attendance-overview-view',path==='/attendance'&&!params.get('class'));document.body.classList.toggle('register-view',path==='/attendance'&&Boolean(params.get('class')));document.body.classList.toggle('gradebook-view',path==='/classes'&&params.get('tab')==='gradebook');document.body.classList.toggle('student-view',path==='/student');sidebar();dirty=false;draft=null;gradeDraft=null;activeRegister=null;const pages={'/assessments':assessmentsPage,'/options':()=>optionChoicesUI.page(params),'/support':()=>supportUI.page(params),'/cover':()=>coverUI.page(params),'/admin':()=>adminUI.page(params),'/family':()=>familyUI.page(params),'/classroom':()=>classroomUI.page(params),'/student-passwords':()=>classroomUI.page(params,true),'/home':()=>home(params),'/messages':()=>homeTools.page(params),'/classes':()=>classesPage(params),'/attendance':()=>attendancePage(params),'/directory':()=>directoryPage(params),'/person':()=>directoryUI.profile(params),'/directory-class':()=>directoryUI.classPage(params),'/student':()=>gradesUI.studentPage(params),'/assessment':()=>gradesUI.assessmentPage(params),'/calendar':()=>calendarPage(params),'/reports':reportsPage,'/cards':()=>cardsPage(params),'/incidents':()=>incidentsPage(params),'/timetable':()=>timetableUI.page(params),'/allocation':allocationPage};$('#main').innerHTML=(currentTeacher.role==='report-reviewer'&&!['/assessments','/options','/support','/cover','/admin','/classroom','/student-passwords','/cards','/student','/assessment','/directory','/person','/directory-class','/attendance','/timetable','/reports','/incidents'].includes(path)?()=>reportsUI.page(params):pages[path]||pages['/home'])();document.title=`${({'/assessments':'Assessment','/options':'Year 10 options','/support':'Technical support','/cover':'Cover','/admin':'Administration','/family':'Family portal','/classroom':'Classroom','/student-passwords':'Student passwords','/home':'Overview','/messages':'Messages','/classes':'My classes','/attendance':'Attendance','/directory':'Directory','/person':'Directory profile','/directory-class':'Class directory','/student':'Student profile','/assessment':'Saved assessment','/calendar':'Calendar','/reports':'Reporting','/cards':'Report cards','/incidents':'Incidents','/allocation':'My allocation','/timetable':'Timetabling'})[path]||'Overview'} · WIST`;previousHash=location.hash;}

function openDialog(title,body,footer='',eyebrow='TEACHER WORKSPACE'){dialogDirty=false;$('#dialog').classList.remove('message-dialog');$('#dialog-content').innerHTML=`<div class="modal-head"><div><div class="eyebrow">${eyebrow}</div><h2 id="dialog-title">${title}</h2></div><button class="close" data-action="close" aria-label="Close dialog">×</button></div><div class="modal-body">${body}<div class="error" role="alert"></div></div>${footer?`<div class="modal-foot">${footer}</div>`:''}`;$('#dialog').showModal();}
function closeDialog(force=false){if(dialogDirty&&!force&&!confirm('Discard the changes in this form?'))return false;$('#dialog').close();dialogDirty=false;return true;}
function formField(label,name,type='text',value='',extra=''){return `<label class="field"><span>${label}</span><input name="${name}" type="${type}" value="${esc(value)}" ${extra}></label>`;}
