function assignmentDialog(id){openDialog('New assignment',`<form id="modal-form" data-form="assignment" data-class="${id}"><div class="form-grid"><label class="field full"><span>Assignment title</span><input name="title" required maxlength="120"></label>${formField('Due date','due','date',today(),'required')}${formField('Maximum marks','points','number','20','min="1" max="1000" required')}<label class="field full"><span>Instructions</span><textarea name="description" rows="4" maxlength="2000"></textarea></label></div></form>`,formFooter('Create assignment'));}
function lessonDialog(id){openDialog('Plan a lesson',`<form id="modal-form" data-form="lesson" data-class="${id}"><div class="form-grid"><label class="field full"><span>Lesson title</span><input name="title" required maxlength="120"></label>${formField('Lesson date','date','date',today(),'required')}<label class="field full"><span>Learning objective</span><textarea name="objective" rows="4" maxlength="2000" required></textarea></label></div></form>`,formFooter('Save lesson'));}
function eventDialog(date){openDialog('Add a personal event',`<form id="modal-form" data-form="event"><div class="form-grid"><label class="field full"><span>Event title</span><input name="title" required maxlength="120"></label>${formField('Date','date','date',date||today(),'required')}${formField('Time (optional)','time','time','','')}</div></form>`,formFooter('Save event'));}
