function reportEditor(id){const r=state.reports.find(r=>r.id===id);if(!r)return;const s=studentById(r.studentId),c=classById(r.classId),edit=r.status==='draft';openDialog(s.name,`${badge({draft:'Draft',pending:'Pending review',approved:'Approved'}[r.status],r.status)} <span class="muted"><small>${c.name}</small></span>${edit?`<br><br><form id="modal-form" data-form="report" data-id="${id}"><div class="form-grid"><label class="field"><span>Attainment grade</span><select name="grade">${options([['','Choose grade'],...['A*','A','B','C','D','E','F','G','U']],r.grade)}</select></label><label class="field"><span>Effort</span><select name="effort">${options([['','Choose effort'],'Excellent','Good','Developing','Needs support'],r.effort)}</select></label><label class="field full"><span>Teacher comment</span><textarea aria-label="Teacher comment" name="comment" rows="7" maxlength="3000" placeholder="Progress, strengths, and next steps…">${esc(r.comment)}</textarea><small class="muted">A grade, effort and at least 20 characters are required to submit.</small></label></div></form>`:`<div class="report-sheet"><img class="wist-logo-report" src="assets/wist-icon.png" alt="WIST" width="192" height="192"><div class="eyebrow">WESTMINSTER INTERNATIONAL SCHOOL TASHKENT</div><h3>October settling-in report</h3><div class="report-meta">${esc(s.name)} · ${yearLabel(s.year)} · ${c.name}<br>Sample report · ${r.status==='approved'?'Approved':'Pending review'}</div><div class="report-grades"><div><span class="eyebrow">ATTAINMENT</span><strong>${esc(r.grade)}</strong></div><div><span class="eyebrow">EFFORT</span><strong>${esc(r.effort)}</strong></div></div><p>${esc(r.comment)}</p><p class="muted">${esc(currentTeacher.name)} · Teacher</p></div>`}`,edit?`<small class="muted">October settling-in report</small><div class="actions">${button('Save draft','save-report',`data-id="${id}"`)}<button type="submit" form="modal-form" class="btn primary">Submit for review</button></div>`:`<small class="muted">${r.status==='approved'?'Approved reports cannot be edited.':'Awaiting review. Approval is an administrator action.'}</small>${button('Print report','print-report')}`,'PROGRESS REPORT');}
function studentDialog(id){const s=students.find(s=>s.id===id);if(!s)return;const enrolled=classes.filter(c=>c.studentIds.includes(s.id));openDialog(s.name,`${person(s)}<br><div class="form-grid"><div class="field"><span>Admission number</span>${s.admissionNumber}</div><div class="field"><span>Form group</span>${s.groupName}</div><div class="field"><span>Fictional date of birth</span>${formatDate(s.dateOfBirth)}</div><div class="field"><span>Status</span>${s.status}</div><div class="field full"><span>Test email</span>${s.schoolEmail}</div></div><br><h3>Your teaching subjects</h3>${enrolled.length?`<ul class="tasks">${enrolled.map(c=>`<li><div><strong>${c.name}</strong><p>${c.room}</p></div></li>`).join('')}</ul>`:'<p class="muted">This student is outside your current subject classes.</p>'}<br><h3>Incident history</h3><p class="muted">${state.incidents.filter(i=>i.studentId===id).length} sample incidents recorded.</p>` ,button('Close','close'),'SAMPLE STUDENT PROFILE');}
function incidentDetail(id){const i=state.incidents.find(i=>i.id===id);if(!i)return;openDialog(esc(i.title),`${person(studentById(i.studentId))}<br>${badge(i.severity,'pending')} <small class="muted">${formatDate(i.date)} · ${i.time} · ${esc(i.location)}</small><div class="report-sheet"><h3>What happened</h3><p>${esc(i.description)}</p><br><h3>Follow-up action</h3><p>${esc(i.followup||'No follow-up action recorded.')}</p></div>`,button('Close','close'),'INCIDENT DETAILS');}
function exportAttendance(){const record=contextCache.get(keyFor(activeRegister.date,activeRegister.classId,activeRegister.period))?.saved;if(!record){toast('Save this register before exporting.');return;}const rows=[['Student ID','Date','Class','Period','Student','Status','Arrival time','Note'],...record.records.map(r=>[studentById(r.studentId).studentNumber,record.date,classById(record.classId).name,record.period,studentById(r.studentId).name,r.status,r.time,r.note])];download(`attendance-${record.date}-period-${record.period}.csv`,csv(rows));toast('Saved register exported.');}
document.addEventListener('click',async e=>{if(e.target.closest('a.skip')){e.preventDefault();$('#main').focus();return;}const a=e.target.closest('[data-action]');if(!a)return;const id=a.dataset.id;if(reportLibraryUI.action(a.dataset.action,a))return;if(timetableUI.action(a.dataset.action,a))return;if(attendanceOverviewUI.action(a.dataset.action,a))return;if(directoryUI.action(a.dataset.action,a))return;if(reportsUI.action(a.dataset.action,a))return;if(homeTools.action(a.dataset.action,a))return;if(gradesUI.handleAction(a.dataset.action,a))return;switch(a.dataset.action){
case 'close':closeDialog();break;
case 'assignment':assignmentDialog(a.dataset.class);break;
case 'lesson':lessonDialog(a.dataset.class);break;
case 'event':eventDialog(a.dataset.date);break;
case 'incident':incidentDialog();break;
case 'incident-detail':incidentDetail(id);break;
case 'student':navigate('/student',{id});break;
case 'student-page':filterStudents(Number(a.dataset.page));break;
case 'register-note':registerNoteDialog(id);break;
case 'arrival-time':arrivalTimeDialog(id);break;
case 'arrival-minute-up':case 'arrival-minute-down':{const input=$('#arrival-clock'),value=input.value||currentArrivalTime(),[hour,minute]=value.split(':').map(Number),total=(hour*60+minute+(a.dataset.action==='arrival-minute-up'?1:-1)+1440)%1440;input.value=String(Math.floor(total/60)).padStart(2,'0')+':'+String(total%60).padStart(2,'0');dialogDirty=true;break;}
case 'arrival-now':$('#arrival-clock').value=currentArrivalTime();dialogDirty=true;break;
case 'apply-register-note':{const record=draft.find(r=>r.studentId===id);record.note=$('#register-note-text').value;const noteButton=$('#note-button-'+id);noteButton.textContent=record.note?'Edit note':'+ Note';noteButton.title=record.note||'Add a lesson note';noteButton.classList.toggle('has-note',Boolean(record.note));closeDialog(true);markDirty();break;}
case 'export-students':download('my-allocated-students.csv',csv([['Admission number','Name','Year','Form','Group','Synthetic date of birth','Test email'],...students.map(s=>[s.admissionNumber,s.name,s.yearLabel,s.form,s.groupName,s.dateOfBirth,s.schoolEmail])]));break;
case 'export-students-json':download('my-allocated-students.json',JSON.stringify({teacher:currentTeacher,students},null,2),'application/json');break;
case 'export-groups':download('my-form-sizes.csv',csv([['Group','Allocated students'],...groups.map(g=>[g.name,g.count])]));break;
case 'report-editor':reportEditor(id);break;
case 'print-report':window.print();break;
case 'save-report':{const data=Object.fromEntries(new FormData($('#modal-form')));if(await mutate(s=>updateReport(s,id,data,false))){dialogDirty=false;closeDialog(true);render();toast('Report draft saved.');}break;}
case 'mark-present':draft=draft.map(r=>({...r,status:'Present',time:''}));document.querySelector('.data-table tbody').innerHTML=draft.map(attendanceRow).join('');$('#attendance-summary').innerHTML=summaryHtml(draft);markDirty();break;
case 'save-attendance':void saveSharedAttendance();break;
case 'retry-register':contextCache.delete(keyFor(activeRegister.date,activeRegister.classId,activeRegister.period));render();break;
case 'register-back':registerBack();break;
case 'discard-register-back':dirty=false;closeDialog(true);leaveRegister();break;
case 'save-register-back':void saveSharedAttendance(true);break;
case 'save-grades':if(await mutate(s=>saveGrades(s,id,gradeDraft))){dirty=false;render();toast('Marks saved.');}break;
case 'cancel-draft':if(!dirty||confirm('Discard your unsaved changes?')){dirty=false;render();}break;
case 'attendance-export':exportAttendance();break;
case 'toggle-lesson':if(await mutate(s=>{const l=s.lessons.find(l=>l.id===id);l.taught=!l.taught;})){render();toast('Lesson progress updated.');}break;
}});
function markDirty(){dirty=true;if($('#save-status'))$('#save-status').textContent='Unsaved changes';}
document.addEventListener('input',e=>{const t=e.target;reportLibraryUI.input(t);timetableUI.input(t);attendanceOverviewUI.input(t);directoryUI.input(t);homeTools.input(t);gradesUI.input(t);reportsUI.input(t);if(t.closest('#dialog')&&t.closest('form'))dialogDirty=true;
if(t.dataset.registerNote){draft.find(r=>r.studentId===t.dataset.registerNote).note=t.value;markDirty();}
if(t.dataset.registerTime){draft.find(r=>r.studentId===t.dataset.registerTime).time=t.value;markDirty();}
if(t.dataset.score){gradeDraft[t.dataset.score]=t.value;const a=state.assignments.find(a=>a.id===($('#grade-assignment')?.value));$('#pct-'+t.dataset.score).textContent=t.value===''?'—':Math.round(Number(t.value)/a.points*100)+'%';markDirty();}
if(t.id==='class-search')filterClasses();if(t.id==='student-search')filterStudents();if(t.id==='card-search')filterCards(false);
});
document.addEventListener('change',e=>{const t=e.target;reportLibraryUI.change(t);timetableUI.change(t);attendanceOverviewUI.change(t);directoryUI.change(t);homeTools.change(t);gradesUI.change(t);reportsUI.change(t);
if(t.dataset.registerStatus){const r=draft.find(r=>r.studentId===t.dataset.registerStatus);r.status=t.value;if(!r.status.startsWith('Late'))r.time='';updateArrivalCell(r);$('#attendance-summary').innerHTML=summaryHtml(draft);markDirty();if(r.status.startsWith('Late'))arrivalTimeDialog(r.studentId);}
if(t.id==='home-date'&&isDate(t.value))navigate('/home',{date:t.value});
if(['attendance-class','attendance-date','attendance-period'].includes(t.id)){if(dirty&&!confirm('Discard your unsaved attendance changes?')){t.value=t.id==='attendance-class'?activeRegister.classId:t.id==='attendance-date'?activeRegister.date:activeRegister.period;return;}if(!isDate($('#attendance-date').value)){showError('Choose a valid attendance date.');return;}dirty=false;navigate('/attendance',{class:$('#attendance-class').value,date:$('#attendance-date').value,period:$('#attendance-period').value});}
if(t.id==='grade-assignment'){if(dirty&&!confirm('Discard your unsaved marks?')){t.value=readRoute().params.get('assignment')||state.assignments.find(a=>a.classId===currentClass().id)?.id;return;}dirty=false;navigate('/classes',{class:currentClass().id,tab:'gradebook',assignment:t.value});}
if(t.id==='class-year')filterClasses();if(t.id==='student-year'){updateFormOptions();filterStudents();}if(t.id==='student-group')filterStudents();if(['card-class','card-year'].includes(t.id))filterCards(true);
});
function filterClasses(){const q=$('#class-search').value.toLowerCase(),year=$('#class-year').value;const list=classes.filter(c=>(c.name+' '+c.subject).toLowerCase().includes(q)&&(!year||String(c.year)===year));$('#class-results').innerHTML=list.map(classCard).join('')||empty('No classes found','Try a different subject or year.');}
function filterStudents(page=1){const q=$('#student-search').value,year=$('#student-year').value,group=$('#student-group').value;$('#student-results').innerHTML=directoryResults(directoryList(q,year,group),page);}
function updateFormOptions(){const year=$('#student-year').value,old=$('#student-group').value;$('#student-group').innerHTML=groupOptions(year,groups.some(g=>g.id===old&&(!year||String(g.year)===year))?old:'');}
function filterCards(navigateRoute){const values={class:$('#card-class').value,year:$('#card-year').value,q:$('#card-search').value};if(navigateRoute){navigate('/cards',values);return;}const focus=$('#card-search'),pos=focus.selectionStart;const params=new URLSearchParams(values);const html=cardsPage(params);const temp=document.createElement('div');temp.innerHTML=html;$('.queue').replaceWith(temp.querySelector('.queue'));history.replaceState(null,'',href('/cards',values));previousHash=location.hash;focus.setSelectionRange(pos,pos);}
document.addEventListener('submit',async e=>{const form=e.target;if(form.id.startsWith('tt-')){e.preventDefault();timetableUI.submit(form);return;}if(form.id==='class-message-form'){e.preventDefault();return;}if(form.id==='arrival-clock-form'){e.preventDefault();applyArrivalTime(form.dataset.id);return;}if(form.id==='global-search'){e.preventDefault();navigate('/directory',{q:$('#search-everywhere').value});return;}if(form.id!=='modal-form')return;e.preventDefault();const data=Object.fromEntries(new FormData(form)),kind=form.dataset.form,id=form.dataset.id;let result=await mutate(s=>{
if(kind==='assignment'){const points=Number(data.points);if(!data.title.trim()||!isDate(data.due)||!Number.isInteger(points)||points<1||points>1000)throw new Error('Enter a title, valid due date and whole-number maximum marks from 1 to 1,000.');s.assignments.push({...data,title:data.title.trim(),points,classId:form.dataset.class,id:crypto.randomUUID()});}
if(kind==='lesson'){if(!isDate(data.date)||!data.title.trim()||!data.objective.trim())throw new Error('Add a title, valid date and learning objective.');s.lessons.push({...data,title:data.title.trim(),classId:form.dataset.class,id:crypto.randomUUID(),taught:false});}
if(kind==='event'){if(!isDate(data.date)||!data.title.trim())throw new Error('Enter a title and a valid event date.');s.events.push({...data,title:data.title.trim(),id:crypto.randomUUID(),type:'Personal'});}
if(kind==='incident'){validateIncidentSelection(data,students,groups);if(!studentById(data.studentId)||!isDate(data.date)||!data.title.trim()||!data.description.trim()||!data.location.trim()||!/^([01]\d|2[0-3]):[0-5]\d$/.test(data.time))throw new Error('Complete the student, title, date, time, location and description.');s.incidents.push({...data,title:data.title.trim(),id:crypto.randomUUID(),reportedBy:currentTeacher.name,teacherId:currentTeacher.id});}
if(kind==='report')updateReport(s,id,data,true);
});if(result){dialogDirty=false;closeDialog(true);render();toast(kind==='report'?'Report submitted for review.':kind==='incident'?'Incident saved locally. No notification sent.':sharedWorkspace?'Saved to shared school records.':'Saved in this browser.');}});
$('#dialog').addEventListener('cancel',e=>{e.preventDefault();closeDialog();});
$('#backup').addEventListener('click',async()=>{let sharedAssessments,sharedMessages,sharedReports,sharedClassroom,sharedIncidents;try{const classroomBackup=await fetch('/api/classroom/backup');if(!classroomBackup.ok)throw Error('Classroom backup unavailable');sharedClassroom=await classroomBackup.json();const incidentBackup=await fetch('/api/incidents/backup');if(!incidentBackup.ok)throw Error('Incident backup unavailable');sharedIncidents=await incidentBackup.json();sharedReports=await reportsUI.api('/backup');sharedMessages=(await homeTools.api('/owned')).messages;sharedAssessments=(await gradesUI.api('/owned')).assessments;const result=await attendanceApi('/owned');schoolState.attendance={...schoolState.attendance,...Object.fromEntries(result.registers.map(r=>[keyFor(r.date,r.classId,r.period),r]))};state=scopedState(schoolState,currentTeacher.id);}catch(error){toast('Shared record backup could not be loaded: '+error.message);return;}let payload={...state,sharedAssessments,sharedMessages,sharedReports,sharedClassroom,sharedIncidents,exportedAt:new Date().toISOString(),sampleData:true};if(storageBroken){try{payload={...payload,unreadableSavedData:localStorage.getItem(STORAGE_KEY)};}catch{}}download(`wist-teacher-backup-${today()}.json`,JSON.stringify(payload,null,2),'application/json');toast('Prototype backup exported.');});
window.addEventListener('beforeunload',e=>{if(dirty||dialogDirty){e.preventDefault();e.returnValue='';}});
window.addEventListener('hashchange',event=>{if(!currentTeacher)return;const beforeHash=new URL(event.oldURL).hash,afterHash=new URL(event.newURL).hash;if(afterHash.startsWith('#/attendance')&&new URLSearchParams(afterHash.split('?')[1]||'').has('class')&&!(beforeHash.startsWith('#/attendance')&&new URLSearchParams(beforeHash.split('?')[1]||'').has('class')))registerReturnHash=beforeHash||'#/home';if((dirty||dialogDirty)&&!confirm('Discard your unsaved changes?')){history.replaceState(null,'',previousHash||'#/home');return;}dirty=false;dialogDirty=false;if($('#dialog').open)closeDialog(true);render();window.scrollTo(0,0);$('#main').focus({preventScroll:true});});
await boot();

function allocationPage(){
 return heading('My teaching allocation',esc(currentTeacher.name)+' · '+esc(currentTeacher.area),'','YOUR ACCOUNT')+'<section class="panel account-panel"><div class="panel-body"><div class="form-grid"><div class="field"><span>Test username</span>'+esc(currentTeacher.username)+'</div><div class="field"><span>Phase</span>'+esc(currentTeacher.phase)+'</div><div class="field full"><span>Form tutor for</span>'+(currentTeacher.formIds.map(id=>groupById(id).name).join(', ')||'No form tutor assignment')+'</div><div class="field full"><span>Curriculum area</span>'+esc(currentTeacher.subjects.join(', '))+'</div></div></div></section><section class="panel"><div class="panel-head"><h2>'+classes.length+' teaching groups</h2><small class="muted">'+students.length+' unique students</small></div><div class="table-wrap"><table class="data-table"><thead><tr><th>Teaching group</th><th>Subject</th><th>Membership</th><th>Students</th></tr></thead><tbody>'+classes.map(c=>'<tr><td><a class="text-button" href="'+href('/classes',{class:c.id,tab:'roster'})+'">'+esc(c.name)+'</a></td><td>'+esc(c.subject)+'</td><td>'+esc(c.enrollmentMode)+'</td><td>'+roster(c.id).length+'</td></tr>').join('')+'</tbody></table></div></section>';
}
function applyTeacherScope(){if(currentTeacher.role==='technician'){document.querySelector('#global-search').style.display='none';document.querySelector('#backup').style.display='none';classes=[];students=[];groups=[];yearGroups=[];timetable=[];state={};$('#teacher-name').textContent=currentTeacher.name;$('#teacher-role').textContent='Technical services';$('#teacher-avatar').textContent=initials(currentTeacher.name);return;}if(['student','parent'].includes(currentTeacher.role)){classes=[];students=[];groups=[];yearGroups=[];timetable=[];state={};$('#teacher-name').textContent=currentTeacher.name;$('#teacher-role').textContent=currentTeacher.role==='parent'?'Parent · Family portal':'Student · '+currentTeacher.groupName;$('#teacher-avatar').textContent=initials(currentTeacher.name);return;}if(currentTeacher.role==='report-reviewer'){classes=schoolClasses;students=schoolStudents;groups=schoolGroups;yearGroups=schoolYearGroups;timetable=[];state=scopedState(schoolState,currentTeacher.id);$('#teacher-name').textContent=currentTeacher.name;$('#teacher-role').textContent=currentTeacher.area;$('#teacher-avatar').textContent='RR';return;}
 classes=classesForTeacher(currentTeacher.id);students=studentsForTeacher(currentTeacher.id);
 groups=schoolGroups.map(g=>({...g,count:students.filter(s=>s.cohort===g.id).length})).filter(g=>g.count>0);
 yearGroups=schoolYearGroups.map(y=>({...y,total:students.filter(s=>String(s.year)===y.value).length,groupCount:groups.filter(g=>String(g.year)===y.value).length})).filter(y=>y.total>0);
 timetable=timetableForTeacher(currentTeacher.id);state=scopedState(schoolState,currentTeacher.id);
 $('#teacher-name').textContent=currentTeacher.name;$('#teacher-role').textContent=currentTeacher.phase+' · '+currentTeacher.area;
 $('#teacher-avatar').textContent=initials(currentTeacher.name);$('#teacher-avatar').title=currentTeacher.username;
}
async function boot(){
 try{const response=await fetch('/api/session',{credentials:'same-origin',cache:'no-store'});if(response.status===401){location.replace('/login.html');return;}if(!response.ok)throw new Error('Could not load the test session.');const session=await response.json();currentTeacher=session.teacher;sharedWorkspace=Boolean(session.features?.sharedWorkspace);if(currentTeacher.role==='technician'){applyTeacherScope();render();return;}if(sharedWorkspace&&currentTeacher.role!=='parent')await syncPublishedTimetable();if(!['student','parent'].includes(currentTeacher.role)){await syncManagedCatalog();if(sharedWorkspace)await syncWorkspace();}if(['student','parent'].includes(currentTeacher.role)){applyTeacherScope();render();return;}if(currentTeacher.role!=='report-reviewer')await syncSharedAttendance();applyTeacherScope();if(currentTeacher.role!=='report-reviewer')await gradesUI.migrate(schoolState,currentTeacher);await reportsUI.migrate(state);await incidentsUI.migrate(schoolState.incidents);render();}
 catch(error){$('#main').innerHTML='<div class="error">'+esc(error.message)+' Start the local server with npm start.</div>';}
}
async function signOut(){
 if((dirty||dialogDirty)&&!confirm('Discard your unsaved changes and sign out?'))return;
 try{const response=await fetch('/api/logout',{method:'POST',credentials:'same-origin'});if(!response.ok)throw new Error('Sign out failed. Please try again.');dirty=false;dialogDirty=false;location.replace('/login.html');}catch(error){toast(error.message);}
}
$('#sign-out').addEventListener('click',signOut);

async function attendanceApi(path,options={}){
 const response=await fetch('/api/attendance'+path,{credentials:'same-origin',cache:'no-store',...options,headers:{'Content-Type':'application/json',...options.headers}});
 const result=await response.json();if(!response.ok)throw new Error(result.error||'Attendance request failed.');return result;
}
async function syncSharedAttendance(){
 const owned=new Set(classesForTeacher(currentTeacher.id).map(c=>c.id));
 const legacy=Object.values(schoolState.attendance).filter(r=>owned.has(r.classId));
 if(legacy.length)await attendanceApi('/import',{method:'POST',body:JSON.stringify({registers:legacy})});
 const result=await attendanceApi('/owned');schoolState.attendance={...Object.fromEntries(Object.entries(schoolState.attendance).filter(([,r])=>!owned.has(r.classId))),...Object.fromEntries(result.registers.map(r=>[keyFor(r.date,r.classId,r.period),r]))};
}
async function loadRegisterContext(target){
 const key=keyFor(target.date,target.classId,target.period);if(contextRequests.has(key))return;contextRequests.add(key);
 try{contextCache.set(key,await attendanceApi('/context?'+new URLSearchParams({date:target.date,classId:target.classId,period:target.period})));}
 catch(error){contextCache.set(key,{error:error.message});}
 finally{contextRequests.delete(key);const route=readRoute();if(!dirty&&route.path==='/attendance'&&activeRegister&&keyFor(activeRegister.date,activeRegister.classId,activeRegister.period)===key)render();}
}
function leaveRegister(){location.hash=(registerReturnHash||href('/classes',{class:activeRegister.classId})).slice(1);}
function registerBack(){
 if(!dirty){leaveRegister();return;}
 openDialog('Save before going back?','<p>Your attendance changes have not been saved yet.</p>',button('Keep editing','close')+button('Discard and Back','discard-register-back')+button('Save and Back','save-register-back','','primary'));
}
async function saveSharedAttendance(goBack=false){
 if(savingAttendance||!draft)return;const target={...activeRegister,records:structuredClone(draft)};savingAttendance=true;
 const controls=[...document.querySelectorAll('main input,main select,main button,#dialog[open] button')].map(el=>({el,disabled:el.disabled}));controls.forEach(({el})=>el.disabled=true);
 try{
  const {register}=await attendanceApi('/register',{method:'PUT',body:JSON.stringify(target)});
  let latest=schoolState,localBackup=true;try{latest=load(localStorage);}catch{localBackup=false;}latest.attendance[keyFor(register.date,register.classId,register.period)]=register;schoolState=latest;
  try{if(localBackup)localStorage.setItem(STORAGE_KEY,JSON.stringify(latest));}catch{localBackup=false;}
  state=scopedState(schoolState,currentTeacher.id);homeTools.refreshDay();attendanceOverviewUI.invalidate();contextCache.set(keyFor(register.date,register.classId,register.period),{saved:register,records:register.records,revision:register.revision,prefilledCount:0});dirty=false;
  if($('#dialog').open)closeDialog(true);if(goBack)leaveRegister();else render();toast(localBackup?'Attendance saved to shared school records.':'Attendance saved to shared records; local backup unavailable.');
 }catch(error){showError(error.message);}
 finally{savingAttendance=false;controls.forEach(({el,disabled})=>{if(el.isConnected)el.disabled=disabled;});}
}
window.addEventListener('focus',()=>{if(!currentTeacher||dirty||dialogDirty||$('#dialog').open||readRoute().path!=='/attendance'||!activeRegister||savingAttendance)return;const key=keyFor(activeRegister.date,activeRegister.classId,activeRegister.period);contextCache.delete(key);void loadRegisterContext({...activeRegister});});

window.addEventListener('focus',()=>{if(currentTeacher&&readRoute().path==='/home'&&!dirty&&!dialogDirty&&!$('#dialog').open)homeTools.refreshDay();});

async function syncManagedCatalog(){const r=await fetch('/api/people-catalog',{credentials:'same-origin',cache:'no-store'});if(!r.ok)throw Error('Could not load managed school records.');applyManagedCatalog(await r.json());}


async function syncPublishedTimetable(){const r=await fetch('/api/classroom/timetable',{credentials:'same-origin',cache:'no-store'});if(!r.ok)throw Error('Could not load the published school timetable.');const {snapshot}=await r.json();if(snapshot){installPublishedTimetable(snapshot);capturePublishedCatalog(snapshot);}}
